parameters.jsCode:
const content = $json.choices?.[0]?.message?.content || '';
let cleaned = content.trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let questions = [];
try {
  questions = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) {
    questions = JSON.parse(match[0]);
  } else {
    throw new Error('Could not parse questions JSON from OpenRouter output');
  }
}

const formatted = (Array.isArray(questions) ? questions : []).map((q, idx) => ({
  questionText: q.questionText || q.question || `Question ${idx + 1}`,
  questionType: q.questionType || 'mcq',
  options: Array.isArray(q.options) && q.options.length >= 2 ? q.options : ['Option A', 'Option B', 'Option C', 'Option D'],
  correctIndex: typeof q.correctIndex === 'number' ? q.correctIndex : 0,
  explanation: q.explanation || 'Verified study concept.'
}));

return [{
  json: {
    success: true,
    model: 'nex-agi/nex-n2.5-pro:free',
    count: formatted.length,
    questions: formatted
  }
}];
